    },
    {
      "field": "input",
      "score": 2,
      "reason": "승인된 제품 사진을 사용한다는 내용이 보존됩니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "배경 장면을 달리한 광고 이미지 후보가 보존됩니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "제품 외형과 브랜드 표현을 유지하고 성능 변경 및 새 효능 문구 추가를 금지하며, 게시가 승인 뒤에 진행됨을 보존합니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가하지 않았습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "광고 담당자가 후보를 검토하고 실제 게시는 승인 뒤에 진행한다는 역할 구분이 보존됩니다."
    }
  ],
  "issues": [],
  "permission_interpretation": "담당자 검토 및 게시 승인 조건을 보존하며, AI가 게시하거나 승인한다고 서술하지 않습니다."
}
